  "check_code": "from datetime import datetime
from pathlib import Path
import re
import sqlite3


SYSTEM = "shortage_risk_monitoring"
TARGET_ALERT_ID = "ALT_20250630_0052"
EXPECTED_PERSON_ID = "PER_CDT3H_0007"


def _db_path(ws, backup=False):
    name = "state.db.pinned_backup" if backup else "state.db"
    return Path(ws).resolve().parent / "system" / SYSTEM / name


def _row(ws, sql, params=()):
    path = _db_path(ws)
    if not path.exists():
        return None
    with sqlite3.connect(path) as connection:
        connection.row_factory = sqlite3.Row
        value = connection.execute(sql, params).fetchone()
    return dict(value) if value is not None else None


def _norm(value):
    return re.sub(r"[\s，,。；;：:、（）()\-_]+", "", str(value or "")).lower()


def check_target_alert_acknowledged(ws):
    row = _row(
        ws,
        "SELECT alert_status, raised_at, acknowledged_at, closed_at FROM risk_alert WHERE alert_id = ?",
        (TARGET_ALERT_ID,),
    )
    if row is None:
        return {"score": 0, "detail": "目标告警不存在"}
    try:
        raised_at = datetime.fromisoformat(row["raised_at"])
        acknowledged_at = datetime.fromisoformat(row["acknowledged_at"])
    except (TypeError, ValueError):
        return {"score": 0, "detail": f"确认时间无效: {row}"}
    passed = (
        row["alert_status"] == "acknowledged"
        and acknowledged_at >= raised_at
        and row["closed_at"] is None
    )
    return {
        "score": 1 if passed else 0,
        "detail": "目标告警已确认且确认时间有效" if passed else f"目标告警后态不正确: {row}",
    }


def check_target_people_assigned(ws):
    row = _row(
        ws,
        "SELECT acknowledged_by_person_id, assignee_person_id FROM risk_alert WHERE alert_id = ?",
        (TARGET_ALERT_ID,),
    )
    passed = row is not None and all(
        row.get(field) == EXPECTED_PERSON_ID
        for field in ("acknowledged_by_person_id", "assignee_person_id")
    )
    return {
        "score": 1 if passed else 0,
        "detail": "确认人和责任人均为当日有效协调人" if passed else f"人员设置不正确: {row}",
    }


def check_target_note_complete(ws):
    row = _row(
        ws,
        "SELECT resolution_note FROM risk_alert WHERE alert_id = ?",
        (TARGET_ALERT_ID,),
    )
    note = "" if row is None else str(row.get("resolution_note") or "")
    normalized = _norm(note)
    has_days = bool(re.search(r"30(?:\.0+)?\s*天", note))
    has_gap = "192" in normalized and "瓶" in normalized and "缺口" in normalized
    has_consultation = (
        any(term in normalized for term in ("感染专科", "感染科", "感染性疾病科"))
        and "会诊" in normalized
    )
    has_daily_feedback = all(term in normalized for term in ("每日", "库存", "反馈"))
    passed = has_days and has_gap and has_consultation and has_daily_feedback
    return {
        "score": 1 if passed else 0,
        "detail": "备注包含天数、缺口、感染专科会诊和每日反馈" if passed else f"备注信息不完整: {note!r}",
    }


def check_other_alerts_unchanged(ws):
    path = _db_path(ws)
    if not path.exists():
        return {"score": 0, "detail": "风险监测数据库缺失"}
    expected = {
        "ALT_20250630_0041": ("acknowledged", "PERSON_ZHOU_MINGHUI", "PERSON_ZHOU_MINGHUI"),
        "ALT_20250630_0043": ("open", None, None),
        "ALT_20250630_0047": ("open", None, None),
    }
    placeholders = ",".join("?" for _ in expected)
    with sqlite3.connect(path) as connection:
        rows = connection.execute(
            "SELECT alert_id, alert_status, acknowledged_by_person_id, assignee_person_id "
            f"FROM risk_alert WHERE alert_id IN ({placeholders}) ORDER BY alert_id",
            tuple(expected),
        ).fetchall()
    actual = {row[0]: tuple(row[1:]) for row in rows}
    passed = actual == expected
    return {
        "score": 1 if passed else 0,
        "detail": "月末定稿的另外三条告警状态和责任归属未改变" if passed else f"非目标定稿告警被修改: {actual}",
    }
